const headers = $json.headers && typeof $json.headers === 'object' ? $json.headers : {};
const queryParams = $json.query && typeof $json.query === 'object' ? $json.query : {};
const configuredWebhookSecret = typeof $env.AI_RECEPTIONIST_WEBHOOK_SECRET === 'string' ? $env.AI_RECEPTIONIST_WEBHOOK_SECRET.trim() : '';
const headerSecret = typeof headers['x-ai-receptionist-secret'] === 'string' ? headers['x-ai-receptionist-secret'].trim() : typeof headers['X-AI-Receptionist-Secret'] === 'string' ? headers['X-AI-Receptionist-Secret'].trim() : '';
const authorizationHeader = typeof headers.authorization === 'string' ? headers.authorization.trim() : typeof headers.Authorization === 'string' ? headers.Authorization.trim() : '';
const authorizationMatch = authorizationHeader.match(/^Bearer\s+(.+)$/i);
const bearerSecret = authorizationMatch ? authorizationMatch[1].trim() : '';
const querySecret = typeof queryParams.secret === 'string' ? queryParams.secret.trim() : '';
const providedWebhookSecret = headerSecret || bearerSecret || querySecret;
const payload = $json.body ?? $json;
const toolCall = payload.message?.toolCallList?.[0] ?? payload.message?.toolCalls?.[0] ?? payload.toolCall ?? null;
const wrappedToolCall = payload.message?.toolWithToolCallList?.[0]?.toolCall ?? null;
const rawArgs = toolCall?.parameters ?? toolCall?.arguments ?? wrappedToolCall?.function?.parameters ?? wrappedToolCall?.function?.arguments ?? toolCall?.function?.arguments ?? payload.arguments ?? payload;
const details = [];
let args = rawArgs;
if (typeof rawArgs === 'string') {
  const trimmedArgs = rawArgs.trim();
  if (!trimmedArgs) {
    args = {};
  } else {
    try {
      args = JSON.parse(trimmedArgs);
    } catch (error) {
      details.push('Invalid JSON arguments: ' + error.message);
      args = {};
    }
  }
}
if (!args || typeof args !== 'object' || Array.isArray(args)) {
  details.push('Request arguments must be a JSON object');
  args = {};
}
if (configuredWebhookSecret && providedWebhookSecret !== configuredWebhookSecret) details.push('webhook request is unauthorized');
const patient = args.patient && typeof args.patient === 'object' && !Array.isArray(args.patient) ? args.patient : null;
const taskType = typeof args.taskType === 'string' ? args.taskType.trim() : '';
const summary = typeof args.summary === 'string' ? args.summary.trim() : '';
const taskId = typeof args.taskId === 'string' ? args.taskId.trim() : '';
const allowedTaskTypes = new Set(['existing_patient_booking', 'reschedule_or_cancel', 'urgent_case', 'general_follow_up']);
const e164Pattern = /^\+[1-9]\d{7,14}$/;
if (!taskId) details.push('taskId is required');
if (!taskType) details.push('taskType is required');
if (taskType && !allowedTaskTypes.has(taskType)) details.push('taskType is invalid');
if (!patient?.fullName) details.push('patient.fullName is required');
if (!patient?.phoneE164) {
  details.push('patient.phoneE164 is required');
} else if (!e164Pattern.test(patient.phoneE164)) {
  details.push('patient.phoneE164 must use E.164 format');
}
if (!summary) details.push('summary is required');
return [{ json: {
  ok: details.length === 0,
  toolCallId: toolCall?.id || wrappedToolCall?.id || payload.toolCallId || null,
  requestId: args.requestId || payload.requestId || null,
  taskId: taskId || null,
  taskType: taskType || null,
  patient,
  summary,
  notes: typeof args.notes === 'string' ? args.notes.trim() : '',
  preferredCallbackWindow: typeof args.preferredCallbackWindow === 'string' ? args.preferredCallbackWindow.trim() : '',
  sourceCallId: args.sourceCallId || payload.call?.id || payload.callId || null,
  validationErrors: details
} }];

const request = $('Parse Request').first().json;
const configuredRecipients = typeof $env.AI_RECEPTIONIST_RECEPTION_SMS_RECIPIENTS === 'string'
  ? $env.AI_RECEPTIONIST_RECEPTION_SMS_RECIPIENTS.split(',').map((value) => value.trim()).filter(Boolean)
  : [];
const sender = typeof $env.AI_RECEPTIONIST_SMS_SENDER === 'string' ? $env.AI_RECEPTIONIST_SMS_SENDER.trim() : '';
const taskTypeLabels = {
  existing_patient_booking: 'istniejacy pacjent - booking',
  reschedule_or_cancel: 'przelozenie lub odwolanie wizyty',
  urgent_case: 'sprawa pilna',
  general_follow_up: 'ogolny follow-up'
};
const parts = [
  `Nowa prosba recepcji: ${taskTypeLabels[request.taskType] || request.taskType}.`,
  `Pacjent: ${request.patient.fullName}, ${request.patient.phoneE164}.`,
  `Summary: ${request.summary}.`
];
if (request.preferredCallbackWindow) parts.push(`Preferowany kontakt: ${request.preferredCallbackWindow}.`);
if (request.notes) parts.push(`Notatki: ${request.notes}.`);
parts.push(`Task ID: ${request.taskId}.`);
if (request.sourceCallId) parts.push(`Call ID: ${request.sourceCallId}.`);
return [{ json: {
  ...request,
  kind: 'reception_follow_up',
  sender: sender || null,
  recipients: configuredRecipients,
  messageBody: parts.join(' ')
} }];

return (async () => {
  const request = $('Prepare SMS').first().json;
  const providerModeRaw = typeof $env.AI_RECEPTIONIST_SMS_PROVIDER === 'string' ? $env.AI_RECEPTIONIST_SMS_PROVIDER.trim().toLowerCase() : '';
  const providerMode = providerModeRaw || 'mock';
  const recipients = Array.isArray(request.recipients)
    ? request.recipients.filter((value) => typeof value === 'string' && value.trim())
    : [];
  const baseResult = {
    toolCallId: request.toolCallId,
    requestId: request.requestId,
    accepted: true,
    delivery: {
      status: 'simulated',
      provider: providerMode,
      recipientCount: recipients.length > 0 ? recipients.length : 1,
      providerMessageId: null
    },
    notification: {
      kind: request.kind,
      taskId: request.taskId,
      body: request.messageBody
    },
    message: 'Powiadomienie SMS dla recepcji zostalo przygotowane.'
  };

  const buildFailure = (code, message, provider, details, recipientCount = recipients.length) => [{ json: {
    toolCallId: request.toolCallId,
    requestId: request.requestId,
    accepted: false,
    delivery: {
      status: 'failed',
      provider,
      recipientCount,
      providerMessageId: null
    },
    message,
    error: {
      code,
      details
    }
  } }];

  const normalizeProviderStatus = (status) => {
    const normalized = typeof status === 'string' ? status.trim().toLowerCase() : '';
    if (normalized === 'sent' || normalized === 'delivered') return 'sent';
    if (normalized === 'queued' || normalized === 'accepted' || normalized === 'scheduled' || normalized === 'sending') return 'queued';
    if (normalized === 'failed' || normalized === 'undelivered' || normalized === 'canceled') return 'failed';
    return 'queued';
  };

  const resolveTwilioPhoneNumber = async () => {
    const configuredPhoneNumber = typeof $env.TWILIO_PHONE_NUMBER === 'string' ? $env.TWILIO_PHONE_NUMBER.trim() : '';
    if (configuredPhoneNumber) {
      return configuredPhoneNumber;
    }

    const accountSid = typeof $env.TWILIO_ACCOUNT_SID === 'string' ? $env.TWILIO_ACCOUNT_SID.trim() : '';
    const authToken = typeof $env.TWILIO_AUTH_TOKEN === 'string' ? $env.TWILIO_AUTH_TOKEN.trim() : '';
    if (!accountSid || !authToken) {
      throw new Error('TWILIO_PHONE_NUMBER is not set and Twilio credentials are unavailable for auto-discovery');
    }

    const authHeader = `Basic ${Buffer.from(`${accountSid}:${authToken}`).toString('base64')}`;
    const response = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${accountSid}/IncomingPhoneNumbers.json?PageSize=20`, {
      headers: {
        authorization: authHeader
      }
    });
    const responseText = await response.text();
    if (!response.ok) {
      throw new Error(`Unable to list Twilio incoming numbers: HTTP ${response.status}${responseText ? ` ${responseText.slice(0, 500)}` : ''}`);
    }

    let responseBody = null;
    if (responseText) {
      try {
        responseBody = JSON.parse(responseText);
      } catch (error) {
        responseBody = null;
      }
    }

    const incomingNumbers = Array.isArray(responseBody?.incoming_phone_numbers)
      ? responseBody.incoming_phone_numbers.filter((item) => typeof item?.phone_number === 'string' && item.phone_number.trim())
      : [];
    if (incomingNumbers.length !== 1) {
      throw new Error(`Expected exactly one Twilio incoming phone number for auto-discovery, found ${incomingNumbers.length}`);
    }

    return incomingNumbers[0].phone_number.trim();
  };

  if (providerMode === 'mock') {
    baseResult.delivery.provider = 'mock';
    return [{ json: baseResult }];
  }

  if (providerMode === 'twilio') {
    if (recipients.length === 0) {
      return buildFailure(
        'SMS_RECIPIENTS_NOT_CONFIGURED',
        'Nie mozna wyslac powiadomienia SMS dla recepcji.',
        'twilio',
        ['AI_RECEPTIONIST_RECEPTION_SMS_RECIPIENTS must contain at least one E.164 number'],
        0
      );
    }

    const accountSid = typeof $env.TWILIO_ACCOUNT_SID === 'string' ? $env.TWILIO_ACCOUNT_SID.trim() : '';
    const authToken = typeof $env.TWILIO_AUTH_TOKEN === 'string' ? $env.TWILIO_AUTH_TOKEN.trim() : '';
    if (!accountSid || !authToken) {
      return buildFailure(
        'SMS_PROVIDER_NOT_CONFIGURED',
        'Nie mozna wyslac powiadomienia SMS dla recepcji.',
        'twilio',
        ['TWILIO_ACCOUNT_SID and TWILIO_AUTH_TOKEN are required for twilio mode']
      );
    }

    let fromNumber;
    try {
      fromNumber = await resolveTwilioPhoneNumber();
    } catch (error) {
      return buildFailure(
        'SMS_PROVIDER_NOT_CONFIGURED',
        'Nie mozna wyslac powiadomienia SMS dla recepcji.',
        'twilio',
        [error.message]
      );
    }

    const authHeader = `Basic ${Buffer.from(`${accountSid}:${authToken}`).toString('base64')}`;
    let results;
    try {
      results = await Promise.all(recipients.map(async (recipient) => {
        const response = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`, {
          method: 'POST',
          headers: {
            authorization: authHeader,
            'content-type': 'application/x-www-form-urlencoded'
          },
          body: new URLSearchParams({
            From: fromNumber,
            To: recipient,
            Body: request.messageBody
          }).toString()
        });
        const responseText = await response.text();
        let responseBody = null;
        if (responseText) {
          try {
            responseBody = JSON.parse(responseText);
          } catch (error) {
            responseBody = null;
          }
        }
        if (!response.ok) {
          throw new Error(`Twilio rejected recipient ${recipient}: HTTP ${response.status}${responseText ? ` ${responseText.slice(0, 500)}` : ''}`);
        }
        return {
          recipient,
          sid: typeof responseBody?.sid === 'string' ? responseBody.sid : null,
          status: normalizeProviderStatus(responseBody?.status)
        };
      }));
    } catch (error) {
      return buildFailure(
        'SMS_PROVIDER_REJECTED',
        'Nie mozna wyslac powiadomienia SMS dla recepcji.',
        'twilio',
        [error.message]
      );
    }

    const normalizedStatus = results.some((item) => item.status === 'failed')
      ? 'failed'
      : results.some((item) => item.status === 'sent')
        ? 'sent'
        : 'queued';

    if (normalizedStatus === 'failed') {
      return buildFailure(
        'SMS_PROVIDER_REJECTED',
        'Nie mozna wyslac powiadomienia SMS dla recepcji.',
        'twilio',
        results.map((item) => `${item.recipient}: ${item.status}`)
      );
    }

    return [{ json: {
      ...baseResult,
      delivery: {
        status: normalizedStatus,
        provider: 'twilio',
        recipientCount: recipients.length,
        providerMessageId: results.map((item) => item.sid).filter(Boolean).join(',') || null
      },
      message: normalizedStatus === 'sent'
        ? 'Powiadomienie SMS dla recepcji zostalo wyslane.'
        : 'Powiadomienie SMS dla recepcji zostalo przekazane do wysylki.'
    } }];
  }

  if (providerMode !== 'webhook') {
    return buildFailure(
      'SMS_PROVIDER_INVALID',
      'Nie mozna wyslac powiadomienia SMS dla recepcji.',
      providerMode,
      [`Unsupported AI_RECEPTIONIST_SMS_PROVIDER: ${providerMode}`]
    );
  }

  const webhookUrl = typeof $env.AI_RECEPTIONIST_SMS_WEBHOOK_URL === 'string' ? $env.AI_RECEPTIONIST_SMS_WEBHOOK_URL.trim() : '';
  if (!webhookUrl) {
    return buildFailure(
      'SMS_PROVIDER_NOT_CONFIGURED',
      'Nie mozna wyslac powiadomienia SMS dla recepcji.',
      'webhook',
      ['AI_RECEPTIONIST_SMS_WEBHOOK_URL is required for webhook mode']
    );
  }

  if (recipients.length === 0) {
    return buildFailure(
      'SMS_RECIPIENTS_NOT_CONFIGURED',
      'Nie mozna wyslac powiadomienia SMS dla recepcji.',
      'webhook',
      ['AI_RECEPTIONIST_RECEPTION_SMS_RECIPIENTS must contain at least one E.164 number'],
      0
    );
  }

  const bearerToken = typeof $env.AI_RECEPTIONIST_SMS_WEBHOOK_BEARER_TOKEN === 'string' ? $env.AI_RECEPTIONIST_SMS_WEBHOOK_BEARER_TOKEN.trim() : '';
  const timeoutMsRaw = Number.parseInt($env.AI_RECEPTIONIST_SMS_WEBHOOK_TIMEOUT_MS || '10000', 10);
  const timeoutMs = Number.isFinite(timeoutMsRaw) && timeoutMsRaw > 0 ? timeoutMsRaw : 10000;
  const headers = { 'content-type': 'application/json' };
  if (bearerToken) headers.authorization = `Bearer ${bearerToken}`;
  const controller = typeof AbortController === 'function' ? new AbortController() : null;
  let timeoutHandle = null;
  if (controller) timeoutHandle = setTimeout(() => controller.abort(), timeoutMs);

  let response;
  let responseText = '';
  try {
    response = await fetch(webhookUrl, {
      method: 'POST',
      headers,
      body: JSON.stringify({
        sender: request.sender,
        to: recipients,
        body: request.messageBody,
        kind: request.kind,
        metadata: {
          requestId: request.requestId,
          taskId: request.taskId,
          taskType: request.taskType,
          sourceCallId: request.sourceCallId || null
        }
      }),
      signal: controller ? controller.signal : undefined
    });
    responseText = await response.text();
  } catch (error) {
    if (timeoutHandle) clearTimeout(timeoutHandle);
    return buildFailure(
      'SMS_PROVIDER_REJECTED',
      'Nie mozna wyslac powiadomienia SMS dla recepcji.',
      'webhook',
      [error.message]
    );
  }

  if (timeoutHandle) clearTimeout(timeoutHandle);

  let responseBody = null;
  if (responseText) {
    try {
      responseBody = JSON.parse(responseText);
    } catch (error) {
      responseBody = null;
    }
  }

  if (!response.ok) {
    const details = [`HTTP ${response.status}`];
    if (responseText) details.push(responseText.slice(0, 500));
    return buildFailure(
      'SMS_PROVIDER_REJECTED',
      'Nie mozna wyslac powiadomienia SMS dla recepcji.',
      'webhook',
      details
    );
  }

  const normalizedStatus = normalizeProviderStatus(responseBody?.status);
  return [{ json: {
    ...baseResult,
    delivery: {
      status: normalizedStatus,
      provider: 'webhook',
      recipientCount: recipients.length,
      providerMessageId: typeof responseBody?.messageId === 'string'
        ? responseBody.messageId
        : typeof responseBody?.id === 'string'
          ? responseBody.id
          : typeof responseBody?.sid === 'string'
            ? responseBody.sid
            : null
    },
    message: normalizedStatus === 'sent'
      ? 'Powiadomienie SMS dla recepcji zostalo wyslane.'
      : 'Powiadomienie SMS dla recepcji zostalo przekazane do wysylki.'
  } }];
})();

const result = {
  requestId: $json.requestId,
  accepted: true,
  delivery: $json.delivery,
  notification: $json.notification,
  message: $json.message
};
const body = $json.toolCallId
  ? { results: [{ toolCallId: $json.toolCallId, result }] }
  : result;
return [{ json: body }];

const validationErrors = $json.validationErrors || [];
const unauthorized = validationErrors.includes('webhook request is unauthorized');
const result = {
  requestId: $json.requestId,
  accepted: false,
  delivery: {
    status: 'failed',
    provider: 'validation',
    recipientCount: 0,
    providerMessageId: null
  },
  message: unauthorized ? 'Nie mozna zweryfikowac wywolania webhooka.' : 'Brakuje danych do przygotowania powiadomienia SMS dla recepcji.',
  error: {
    code: unauthorized ? 'UNAUTHORIZED' : 'VALIDATION_ERROR',
    details: validationErrors
  }
};
const body = $json.toolCallId
  ? { results: [{ toolCallId: $json.toolCallId, result }] }
  : result;
return [{ json: body }];

const result = {
  requestId: $json.requestId,
  accepted: false,
  delivery: $json.delivery || {
    status: 'failed',
    provider: 'unknown',
    recipientCount: 0,
    providerMessageId: null
  },
  message: $json.message || 'Nie mozna wyslac powiadomienia SMS dla recepcji.',
  error: $json.error || {
    code: 'SMS_PROVIDER_REJECTED',
    details: []
  }
};
const body = $json.toolCallId
  ? { results: [{ toolCallId: $json.toolCallId, result }] }
  : result;
return [{ json: body }];
